<?php namespace App\Core;
final class Router{private array $routes=[];public function get(string $p,array $h):void{$this->add('GET',$p,$h);}public function post(string $p,array $h):void{$this->add('POST',$p,$h);}private function add(string $m,string $p,array $h):void{$this->routes[$m][]=[$p,$h];}public function dispatch(string $method,string $uri):void{foreach($this->routes[$method]??[] as [$path,$handler]){$regex='#^'.preg_replace('/\{[^}]+\}/','([^/]+)',$path).'$#';if(preg_match($regex,$uri,$matches)){array_shift($matches);[$class,$action]=$handler;(new $class)->$action(...$matches);return;}}http_response_code(404);$content=dirname(__DIR__).'/Views/errors/404.php';require dirname(__DIR__).'/Views/layouts/app.php';}}
